#define MTP_SCHEMA_COUNT \
    (sizeof(mtp_schema_ctors) / sizeof(mtp_schema_ctors[0]))

const struct mtp_ctor *
mtp_schema_lookup(uint32_t id)
{
	size_t	lo, hi, mid;

	lo = 0;
	hi = MTP_SCHEMA_COUNT;
	while (lo < hi) {
		mid = lo + (hi - lo) / 2;
		if (mtp_schema_ctors[mid].id == id) {
			return (&mtp_schema_ctors[mid]);
		}
		if (mtp_schema_ctors[mid].id < id) {
			lo = mid + 1;
		} else {
			hi = mid;
		}
	}
	return (NULL);
}

int
mtp_schema_layer(void)
{
	return (MTP_LAYER);
}
